class SlidingWindowRateLimiter {
  private windowSizeMs: number;
  private maxRequests: number;
  private requestLogs: Map<string, number[]>;

  constructor(windowSizeMs: number, maxRequests: number) {
    this.windowSizeMs = windowSizeMs;
    this.maxRequests = maxRequests;
    this.requestLogs = new Map();
  }

  public allowRequest(userId: string, timestampMs: number): boolean {
    const timestamps = this.requestLogs.get(userId) || [];
    const windowStart = timestampMs - this.windowSizeMs;
    const validTimestamps = timestamps.filter(t => t > windowStart);

    if (validTimestamps.length < this.maxRequests) {
      validTimestamps.push(timestampMs);
      this.requestLogs.set(userId, validTimestamps);
      return true;
    }
    return false;
  }
}

